ALTER POLICY "admins insert routes" ON civic_department_routes WITH CHECK(public.can_manage_service_area(auth.uid(),coverage_id));
ALTER POLICY "admins update routes" ON civic_department_routes USING(public.can_manage_service_area(auth.uid(),coverage_id)) WITH CHECK(public.can_manage_service_area(auth.uid(),coverage_id));
CREATE OR REPLACE FUNCTION public.guard_staff_area_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE area text; BEGIN IF cardinality(NEW.coverage_ids)=0 THEN RAISE EXCEPTION 'Staff service area required'; END IF; IF auth.uid() IS NOT NULL AND (TG_OP='INSERT' OR NEW.coverage_ids IS DISTINCT FROM OLD.coverage_ids) THEN FOREACH area IN ARRAY NEW.coverage_ids LOOP IF NOT public.can_manage_service_area(auth.uid(),area) THEN RAISE EXCEPTION 'Staff service area outside administrator permission'; END IF; END LOOP; END IF; IF EXISTS(SELECT 1 FROM civic_teams t WHERE t.id=ANY(NEW.team_ids) AND NOT t.coverage_id=ANY(NEW.coverage_ids)) THEN RAISE EXCEPTION 'Staff team outside assigned service areas'; END IF; RETURN NEW; END $$;
CREATE TRIGGER staff_area_assignment_guard BEFORE INSERT OR UPDATE ON staff_profiles FOR EACH ROW EXECUTE FUNCTION guard_staff_area_assignment();
CREATE OR REPLACE FUNCTION public.guard_admin_area_configuration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT EXISTS(SELECT 1 FROM admin_permissions WHERE user_id=auth.uid() AND is_super_admin AND public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Super Admin required for unscoped administrator operation'; END IF; RETURN NEW; END $$;
CREATE TRIGGER admin_account_scope_guard BEFORE INSERT OR UPDATE ON admin_permissions FOR EACH ROW EXECUTE FUNCTION guard_admin_area_configuration();
DO $patch$ DECLARE s text; BEGIN s:=pg_get_functiondef('public.admin_provision_account(uuid,text,jsonb,uuid)'::regprocedure); s:=replace(s,'INSERT INTO public.user_roles(user_id,role)','IF NOT EXISTS(SELECT 1 FROM admin_permissions WHERE user_id=_actor AND is_super_admin) THEN RAISE EXCEPTION ''Super Admin required for account provisioning during multi-area rollout''; END IF; INSERT INTO public.user_roles(user_id,role)'); EXECUTE s; END $patch$;